19	const SOURCE_LABELS: Record<string, string> = {
20	  manual: "Manual",
21	  penjualan: "Penjualan",
22	  void: "Void",
23	  pembelian: "Pembelian",
24	  beban: "Beban",
25	  payroll: "Payroll",
26	  koreksi: "Koreksi",
27	};
28	
29	const SOURCE_PILL_TONE: Record<string, PillTone> = {
30	  manual: "zinc",
31	  penjualan: "green",
32	  void: "red",
33	  pembelian: "amber",
34	  beban: "amber",
35	  payroll: "blue",
36	  koreksi: "red",
