51	export default async function JurnalPage({
52	  params,
53	  searchParams,
54	}: {
55	  params: Promise<{ businessId: string }>;
56	  searchParams: Promise<{ period?: string; from?: string; to?: string }>;
57	}) {
58	  const { businessId } = await params;
59	  const { period: periodParam, from, to } = await searchParams;
60	  const cookieStore = await cookies();
61	  const period = parsePeriod(periodParam ?? cookieStore.get(PERIOD_COOKIE_NAME)?.value);
62	  const { fromIso, toIsoExclusive } = getPeriodRange(period, from, to);
63	
64	  const supabase = await createClient();
65	
66	  const { data: business } = await supabase
67	    .from("businesses")
68	    .select("id, name")
69	    .eq("id", businessId)
70	    .single();
71	
72	  if (!business) {
73	    notFound();
74	  }
75	
76	  const { data: accounts } = await supabase
77	    .from("accounts")
78	    .select("code, name, type, normal_balance")
79	    .eq("business_id", businessId)
80	    .order("code", { ascending: true });
81	
82	  let entryQuery = supabase
83	    .from("journal_entries")
84	    .select("id, date, description, source, journal_lines(debit, credit, accounts(code, name))")
85	    .eq("business_id", businessId)
86	    .order("date", { ascending: false });
87	  if (fromIso) entryQuery = entryQuery.gte("date", fromIso);
88	  if (toIsoExclusive) entryQuery = entryQuery.lt("date", toIsoExclusive);
89	  const { data: entries } = await entryQuery;
90	
91	  // Terlepas dari filter periode yang sedang aktif — sebuah jurnal manual
92	  // lama (di luar rentang tanggal yang sedang dilihat) tetap tidak boleh
93	  // ditawari tombol "Koreksi" lagi kalau sudah pernah dikoreksi sebelumnya.
94	  const { data: reversals } = await supabase
95	    .from("journal_entries")
96	    .select("source_id")
97	    .eq("business_id", businessId)
98	    .eq("source", "koreksi");
99	  const reversedEntryIds = new Set((reversals ?? []).map((r) => r.source_id));
100	
101	  const boundAddJournalEntry = addJournalEntry.bind(null, businessId);
102	  const today = todayWibDateString();
103	
104	  const entryTotals = (entries ?? []).map((e) => {
105	    const lines = e.journal_lines as unknown as { debit: number; credit: number }[];
106	    return lines.reduce((s, l) => s + Number(l.debit), 0);
107	  });
108	  const totalNominal = entryTotals.reduce((s, v) => s + v, 0);
109	  const periodQuery =
110	    period === "custom"
111	      ? `period=custom${from ? `&from=${from}` : ""}${to ? `&to=${to}` : ""}`
112	      : `period=${period}`;
113	
114	  return (
115	    <div className="w-full max-w-2xl">
116	      <div className="flex flex-wrap items-center justify-between gap-2">
117	        <div>
118	          <h1 className="text-lg font-bold text-zinc-900">Jurnal Transaksi — {business.name}</h1>
119	          <p className="mt-0.5 text-xs text-zinc-500">{PERIOD_DESCRIPTIONS[period]}</p>
120	        </div>
121	        <PeriodTabs basePath={`/business/${businessId}/accounting/jurnal`} period={period} />
122	      </div>
123	
124	      {period === "custom" && (
125	        <form
126	          method="get"
127	          className="mt-4 flex flex-wrap items-end gap-3 rounded-xl bg-white shadow-sm p-4"
128	        >
129	          <input type="hidden" name="period" value="custom" />
130	          <label className="text-xs font-medium text-zinc-600">
131	            Dari
132	            <input
133	              type="date"
134	              name="from"
135	              defaultValue={from}
136	              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
137	            />
138	          </label>
139	          <label className="text-xs font-medium text-zinc-600">
140	            Sampai
141	            <input
142	              type="date"
143	              name="to"
144	              defaultValue={to}
145	              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
146	            />
147	          </label>
148	          <button
149	            type="submit"
150	            className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white hover:bg-brand-700"
151	          >
152	            Terapkan
153	          </button>
154	        </form>
155	      )}
156	
157	      <div className="mt-5 grid grid-cols-2 gap-3">
158	        <StatCard label="Jumlah Entri" value={String((entries ?? []).length)} icon={BookOpen} tone="zinc" />
159	        <StatCard label="Total Nominal" value={formatRupiah(totalNominal)} icon={Wallet} tone="brand" />
160	      </div>
161	
162	      <a
163	        href={`/business/${businessId}/export?${periodQuery}`}
164	        className="mt-3 flex items-center justify-center gap-1.5 rounded-xl border border-zinc-200 bg-white py-2.5 text-xs font-bold text-zinc-700 shadow-sm transition-colors hover:bg-zinc-50"
165	      >
166	        📊 Export Semua Laporan Akuntansi (Excel)
167	      </a>
168	
169	      <div className="mt-4 rounded-xl bg-white shadow-sm p-5">
170	        <h2 className="mb-1 text-sm font-semibold text-zinc-900">+ Jurnal Manual</h2>
171	        <p className="mb-4 text-[11px] text-zinc-400">
172	          Penjualan &amp; void sudah otomatis ter-posting dari POS. Gunakan ini untuk transaksi
173	          lain (setoran modal, dll). Salah input? Jurnal yang sudah diposting tidak bisa diedit
174	          — klik &quot;↩ Koreksi&quot; pada jurnal tersebut untuk membalikkannya secara otomatis,
175	          lalu posting jurnal baru yang benar.
176	        </p>
177	        <AddJournalForm action={boundAddJournalEntry} today={today} accounts={accounts ?? []} />
178	      </div>
179	
180	      <div className="mt-4 space-y-3">
181	        {(entries ?? []).length === 0 && (
182	          <p className="rounded-2xl border border-dashed border-zinc-200 bg-white px-4 py-10 text-center text-sm text-zinc-300">
183	            Belum ada jurnal di periode ini.
184	          </p>
185	        )}
186	        {(entries ?? []).map((e) => {
187	          const lines = e.journal_lines as unknown as {
188	            debit: number;
189	            credit: number;
190	            accounts: { code: string; name: string } | null;
191	          }[];
192	          const total = lines.reduce((s, l) => s + Number(l.debit), 0);
193	          return (
194	            <div key={e.id} className="overflow-hidden rounded-xl bg-white shadow-sm">
195	              <div className="flex items-center justify-between gap-2 border-b border-zinc-100 px-4 py-3">
196	                <div className="min-w-0">
197	                  <p className="truncate text-sm font-semibold text-zinc-900">{e.description}</p>
198	                  <p className="text-[11px] text-zinc-400">{formatDate(e.date)}</p>
199	                </div>
200	                <div className="flex shrink-0 items-center gap-2">
201	                  <PillBadge tone={SOURCE_PILL_TONE[e.source] ?? "zinc"}>
202	                    {SOURCE_LABELS[e.source] ?? e.source}
203	                  </PillBadge>
204	                  <span className="text-xs font-bold text-zinc-700">{formatRupiah(total)}</span>
205	                </div>
206	              </div>
207	              <div className="divide-y divide-zinc-50 px-4">
208	                {lines.map((l, i) => (
209	                  <div key={i} className="flex items-center justify-between py-1.5 text-xs">
210	                    <span className="text-zinc-600">
211	                      {l.accounts?.code} — {l.accounts?.name}
212	                    </span>
213	                    <span className="font-medium text-zinc-800">
214	                      {Number(l.debit) > 0 ? formatRupiah(l.debit) : ""}
215	                      {Number(l.credit) > 0 ? `(${formatRupiah(l.credit)})` : ""}
216	                    </span>
217	                  </div>
218	                ))}
219	              </div>
220	              {e.source === "manual" && !reversedEntryIds.has(e.id) && (
221	                <ReverseJournalButton businessId={businessId} entryId={e.id} />
222	              )}
223	              <div className="h-2" />
224	            </div>
225	          );
226	        })}
227	      </div>
228	    </div>
229	  );
230	}
