1	export type Period = "today" | "week" | "month" | "all" | "custom";
2	
3	// Cookie yang menyimpan pilihan periode terakhir supaya persist lintas
4	// halaman laporan/akuntansi (Fase 7 — sinkronisasi periode global). Cuma
5	// nama string biasa, aman diimpor dari client maupun server component.
6	export const PERIOD_COOKIE_NAME = "kk_period";
7	
8	export const PERIOD_LABELS: Record<Period, string> = {
9	  today: "Hari Ini",
10	  week: "7 Hari",
11	  month: "Bulan Ini",
12	  all: "Semua",
13	  custom: "📅 Kustom",
14	};
15	
16	export const PERIOD_DESCRIPTIONS: Record<Period, string> = {
17	  today: "Hari ini",
18	  week: "7 hari terakhir",
19	  month: "Bulan ini",
20	  all: "Semua waktu",
21	  custom: "Periode kustom",
22	};
23	
24	// Seluruh UI berbahasa Indonesia; batas hari & jam laporan dihitung di zona WIB,
25	// bukan zona server (yang bisa saja UTC saat production).
26	export const REPORT_TIMEZONE = "Asia/Jakarta";
27	
28	export function parsePeriod(value: string | undefined): Period {
29	  return (["today", "week", "month", "all", "custom"] as const).includes(value as Period)
30	    ? (value as Period)
31	    : "today";
32	}
33	
34	function todayStr() {
35	  return new Date().toLocaleDateString("en-CA", { timeZone: REPORT_TIMEZONE });
36	}
37	
38	function addDaysStr(dateStr: string, days: number) {
39	  const d = new Date(`${dateStr}T00:00:00Z`);
40	  d.setUTCDate(d.getUTCDate() + days);
41	  return d.toISOString().slice(0, 10);
42	}
43	
44	/** Ubah tanggal lokal WIB (YYYY-MM-DD) jadi timestamp UTC awal hari itu. */
45	function wibStartOfDay(dateStr: string) {
46	  return `${dateStr}T00:00:00+07:00`;
47	}
48	
49	export type DateRange = { fromIso: string | null; toIsoExclusive: string | null };
50	
51	/**
52	 * Rentang timestamptz [fromIso, toIsoExclusive) untuk filter kolom
53	 * `transactions.date` sesuai periode laporan.
54	 */
55	export function getPeriodRange(
56	  period: Period,
57	  customFrom?: string,
58	  customTo?: string,
59	): DateRange {
60	  const today = todayStr();
61	  if (period === "today") {
62	    return { fromIso: wibStartOfDay(today), toIsoExclusive: null };
63	  }
64	  if (period === "week") {
65	    return { fromIso: wibStartOfDay(addDaysStr(today, -6)), toIsoExclusive: null };
66	  }
67	  if (period === "month") {
68	    return { fromIso: wibStartOfDay(`${today.slice(0, 7)}-01`), toIsoExclusive: null };
69	  }
70	  if (period === "custom") {
71	    const isDate = (s: string | undefined): s is string => !!s && /^\d{4}-\d{2}-\d{2}$/.test(s);
72	    return {
73	      fromIso: isDate(customFrom) ? wibStartOfDay(customFrom) : null,
74	      toIsoExclusive: isDate(customTo) ? wibStartOfDay(addDaysStr(customTo, 1)) : null,
75	    };
76	  }
77	  return { fromIso: null, toIsoExclusive: null };
78	}
