19	export default async function NeracaPage({
20	  params,
21	  searchParams,
22	}: {
23	  params: Promise<{ businessId: string }>;
24	  searchParams: Promise<{ date?: string }>;
25	}) {
26	  const { businessId } = await params;
27	  const { date } = await searchParams;
28	  const asOfDate = /^\d{4}-\d{2}-\d{2}$/.test(date ?? "") ? (date as string) : todayWibDateString();
29	  const asOfIso = `${asOfDate}T23:59:59+07:00`;
30	
31	  const supabase = await createClient();
32	
33	  const { data: business } = await supabase
34	    .from("businesses")
35	    .select("id, name")
36	    .eq("id", businessId)
37	    .single();
38	
39	  if (!business) {
40	    notFound();
41	  }
42	
43	  const { data: accounts } = await supabase
44	    .from("accounts")
45	    .select("id, code, name, type, normal_balance")
46	    .eq("business_id", businessId)
47	    .order("code", { ascending: true });
48	
49	  const { data: entries } = await supabase
50	    .from("journal_entries")
51	    .select("journal_lines(debit, credit, account_id)")
52	    .eq("business_id", businessId)
53	    .lte("date", asOfIso);
54	
55	  const balanceByAccount = new Map<string, number>();
56	  for (const entry of entries ?? []) {
57	    const lines = entry.journal_lines as unknown as {
58	      debit: number;
59	      credit: number;
60	      account_id: string;
61	    }[];
62	    for (const l of lines) {
63	      const cur = balanceByAccount.get(l.account_id) ?? 0;
64	      balanceByAccount.set(l.account_id, cur + Number(l.debit) - Number(l.credit));
65	    }
66	  }
67	
68	  function balanceOf(a: { id: string; normal_balance: string }) {
69	    const raw = balanceByAccount.get(a.id) ?? 0;
70	    return a.normal_balance === "debit" ? raw : -raw;
71	  }
72	
73	  const asetRows = (accounts ?? []).filter((a) => a.type === "aset").map((a) => ({ ...a, balance: balanceOf(a) }));
74	  const kewajibanRows = (accounts ?? []).filter((a) => a.type === "kewajiban").map((a) => ({ ...a, balance: balanceOf(a) }));
75	  const modalRows = (accounts ?? []).filter((a) => a.type === "modal").map((a) => ({ ...a, balance: balanceOf(a) }));
76	  const pendapatanRows = (accounts ?? []).filter((a) => a.type === "pendapatan").map((a) => ({ ...a, balance: balanceOf(a) }));
77	  const bebanRows = (accounts ?? []).filter((a) => a.type === "beban").map((a) => ({ ...a, balance: balanceOf(a) }));
78	
79	  const totalAset = asetRows.reduce((s, a) => s + a.balance, 0);
80	  const totalKewajiban = kewajibanRows.reduce((s, a) => s + a.balance, 0);
81	  const totalModalRecorded = modalRows.reduce((s, a) => s + a.balance, 0);
82	  const totalPendapatan = pendapatanRows.reduce((s, a) => s + a.balance, 0);
83	  const totalBeban = bebanRows.reduce((s, a) => s + a.balance, 0);
84	  const labaBerjalan = totalPendapatan - totalBeban;
85	  const totalModal = totalModalRecorded + labaBerjalan;
86	  const selisih = totalAset - (totalKewajiban + totalModal);
87	
88	  return (
89	    <div className="w-full max-w-3xl">
90	      <div className="flex flex-wrap items-center justify-between gap-2">
91	        <div>
92	          <h1 className="text-lg font-bold text-zinc-900">Neraca — {business.name}</h1>
93	          <p className="mt-0.5 text-xs text-zinc-500">Per tanggal {asOfDate}</p>
94	        </div>
95	        <form method="get" className="flex items-center gap-2">
96	          <input
97	            type="date"
98	            name="date"
99	            defaultValue={asOfDate}
100	            className="rounded-lg border border-zinc-200 px-2.5 py-1.5 text-xs"
101	          />
102	          <button
103	            type="submit"
104	            className="rounded-lg bg-brand-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-700"
105	          >
106	            Tampilkan
107	          </button>
108	        </form>
109	      </div>
110	
111	      <div className="mt-5 grid grid-cols-2 gap-3 lg:grid-cols-4">
112	        <StatCard label="Total Aset" value={formatRupiah(totalAset)} icon={Landmark} tone="blue" />
113	        <StatCard label="Total Kewajiban" value={formatRupiah(totalKewajiban)} icon={Scale3D} tone="amber" />
114	        <StatCard label="Total Modal" value={formatRupiah(totalModal)} icon={Wallet} tone="brand" />
115	        <StatCard
116	          label="Status"
117	          value={Math.abs(selisih) < 1 ? "Seimbang" : "Selisih"}
118	          sub={Math.abs(selisih) < 1 ? undefined : formatRupiah(selisih)}
119	          icon={Math.abs(selisih) < 1 ? CheckCircle2 : AlertTriangle}
120	          tone={Math.abs(selisih) < 1 ? "brand" : "red"}
121	        />
122	      </div>
123	
124	      <div className="mt-4 grid gap-4 sm:grid-cols-2">
125	        <div className="overflow-hidden rounded-2xl border border-zinc-200 bg-white">
126	          <div className="border-b border-zinc-100 px-4 py-3">
127	            <h2 className="text-sm font-bold text-zinc-900">{TYPE_LABELS.aset}</h2>
128	          </div>
129	          <div className="divide-y divide-zinc-50 px-4">
130	            {asetRows.map((a) => (
131	              <div key={a.id} className="flex items-center justify-between py-2 text-xs">
132	                <span className="text-zinc-600">{a.name}</span>
133	                <span className="font-medium text-zinc-800">{formatRupiah(a.balance)}</span>
134	              </div>
135	            ))}
136	          </div>
137	          <div className="flex items-center justify-between border-t border-zinc-100 px-4 py-3 text-sm font-bold text-zinc-900">
138	            <span>Total Aset</span>
139	            <span>{formatRupiah(totalAset)}</span>
140	          </div>
141	        </div>
142	
143	        <div className="space-y-4">
144	          <div className="overflow-hidden rounded-2xl border border-zinc-200 bg-white">
145	            <div className="border-b border-zinc-100 px-4 py-3">
146	              <h2 className="text-sm font-bold text-zinc-900">{TYPE_LABELS.kewajiban}</h2>
147	            </div>
148	            <div className="divide-y divide-zinc-50 px-4">
149	              {kewajibanRows.map((a) => (
150	                <div key={a.id} className="flex items-center justify-between py-2 text-xs">
151	                  <span className="text-zinc-600">{a.name}</span>
152	                  <span className="font-medium text-zinc-800">{formatRupiah(a.balance)}</span>
153	                </div>
154	              ))}
155	            </div>
156	            <div className="flex items-center justify-between border-t border-zinc-100 px-4 py-3 text-sm font-bold text-zinc-900">
157	              <span>Total Kewajiban</span>
158	              <span>{formatRupiah(totalKewajiban)}</span>
159	            </div>
160	          </div>
161	
