29	  params: Promise<{ businessId: string }>;
30	  searchParams: Promise<{ period?: string; from?: string; to?: string }>;
31	}) {
32	  const { businessId } = await params;
33	  const { period: periodParam, from, to } = await searchParams;
34	  const cookieStore = await cookies();
35	  const period = parsePeriod(periodParam ?? cookieStore.get(PERIOD_COOKIE_NAME)?.value);
36	  const { fromIso, toIsoExclusive } = getPeriodRange(period, from, to);
37	
38	  const supabase = await createClient();
39	
40	  const { data: business } = await supabase
41	    .from("businesses")
42	    .select("id, name")
43	    .eq("id", businessId)
44	    .single();
45	
46	  if (!business) {
47	    notFound();
48	  }
49	
50	  const { data: accounts } = await supabase
51	    .from("accounts")
52	    .select("id, code, name, type")
53	    .eq("business_id", businessId);
54	
55	  const accountMap = new Map((accounts ?? []).map((a) => [a.id, a]));
56	  const kasAccountId = (accounts ?? []).find((a) => a.code === KAS_ACCOUNT_CODE)?.id;
57	
58	  // Saldo kas sebelum periode ini (untuk saldo awal).
59	  let openingBalance = 0;
60	  if (kasAccountId && fromIso) {
61	    const { data: priorEntries } = await supabase
62	      .from("journal_entries")
63	      .select("journal_lines(debit, credit, account_id)")
64	      .eq("business_id", businessId)
65	      .lt("date", fromIso);
66	    for (const e of priorEntries ?? []) {
67	      const lines = e.journal_lines as unknown as { debit: number; credit: number; account_id: string }[];
68	      for (const l of lines) {
69	        if (l.account_id === kasAccountId) {
70	          openingBalance += Number(l.debit) - Number(l.credit);
71	        }
72	      }
73	    }
74	  }
75	
76	  // Arus kas di periode ini. Setiap entry jurnal yang punya baris Kas & Bank
77	  // diklasifikasikan Operasional/Investasi/Pendanaan berdasarkan akun
78	  // lawannya (bukan `journal_entries.source`, karena RPC manual-entry yang
