89	  type Bucket = "operasional" | "investasi" | "pendanaan";
90	  const byLabel = new Map<Bucket, Map<string, { masuk: number; keluar: number }>>([
91	    ["operasional", new Map()],
92	    ["investasi", new Map()],
93	    ["pendanaan", new Map()],
94	  ]);
