152	      </div>
153	
154	      {period === "custom" && (
155	        <form
156	          method="get"
157	          className="mt-4 flex flex-wrap items-end gap-3 rounded-2xl border border-zinc-200 bg-white p-4"
158	        >
159	          <input type="hidden" name="period" value="custom" />
160	          <label className="text-xs font-medium text-zinc-600">
161	            Dari
162	            <input
163	              type="date"
164	              name="from"
165	              defaultValue={from}
166	              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
167	            />
168	          </label>
169	          <label className="text-xs font-medium text-zinc-600">
170	            Sampai
171	            <input
172	              type="date"
173	              name="to"
174	              defaultValue={to}
175	              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
176	            />
177	          </label>
178	          <button
179	            type="submit"
180	            className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white hover:bg-brand-700"
181	          >
182	            Terapkan
183	          </button>
184	        </form>
185	      )}
186	
187	      <div className="mt-5 grid grid-cols-3 gap-3">
188	        <StatCard label="Kas Masuk" value={formatRupiah(totalMasuk)} icon={TrendingUp} tone="brand" />
189	        <StatCard label="Kas Keluar" value={formatRupiah(totalKeluar)} icon={TrendingDown} tone="red" />
190	        <StatCard
191	          label="Saldo Kas Akhir"
192	          value={formatRupiah(closingBalance)}
193	          icon={Wallet}
194	          tone={closingBalance >= 0 ? "brand" : "red"}
195	        />
196	      </div>
