8	function formatRupiah(value: number) {
9	  const sign = value < 0 ? "-" : "";
10	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
11	}
12	
13	function formatRupiahShort(value: number) {
14	  const abs = Math.abs(value);
15	  const sign = value < 0 ? "-" : "";
16	  if (abs >= 1_000_000) return `${sign}Rp${(abs / 1_000_000).toFixed(1)} Jt`;
17	  if (abs >= 1_000) return `${sign}Rp${Math.round(abs / 1_000)} Rb`;
18	  return formatRupiah(value);
19	}
20	
21	function todayStr() {
22	  return new Date().toLocaleDateString("en-CA", { timeZone: REPORT_TIMEZONE });
23	}
24	
25	function monthLabel(monthStr: string) {
26	  return new Date(`${monthStr}-01T00:00:00Z`).toLocaleDateString("id-ID", {
27	    month: "long",
28	    year: "numeric",
29	    timeZone: "UTC",
30	  });
31	}
32	
33	function wibStartOfDay(dateStr: string) {
34	  return `${dateStr}T00:00:00+07:00`;
35	}
